#pragma once

#include <optional>
#include <span>
#include "common/common_types.h"
#include "core/arm/aot/abi.h"

namespace Memory {
class MemorySystem;
struct PageTable;
} // namespace Memory

namespace Core::Aot {

/// Translated guest code linked into this build (generated by dekui_aot), or
/// nullptr when the build has none.
const DekuiAot::Abi::Module* LinkedModule();

/// Called by the NCCH loader once a process image is final (patches applied).
/// AOT code is enabled only for MM3D and only if the image is byte-identical
/// to the one the module was generated from.
void OnCodeLoaded(u64 program_id, std::span<const u8> image);

/// Guest instruction-cache maintenance (svcInvalidateInstructionCacheRange and
/// friends): translated code for those addresses is no longer trusted.
void Invalidate(u32 start, std::size_t length);
void InvalidateAll();

/// Block for `descriptor`, or nullptr if it must run on the fallback backend.
DekuiAot::Abi::BlockFn Lookup(u64 descriptor);

/// What a CPU backend provides while translated code runs on it. Guest state
/// lives in the backend between runs; Load/Store move it in and out.
class Host {
public:
    virtual ~Host() = default;

    virtual void Load(DekuiAot::Abi::State& state) = 0;
    virtual void Store(const DekuiAot::Abi::State& state) = 0;

    /// Called with backend state current (after Store); the runner reloads it.
    virtual void CallSVC(u32 swi) = 0;
    virtual void ExceptionRaised(u32 pc, u32 exception) = 0;

    /// True once the emulator asked this core to stop (reschedule, break).
    virtual bool HaltRequested() = 0;
    virtual u64 TicksRemaining() = 0;
    virtual void AddTicks(u64 ticks) = 0;

    virtual u64 ExclusiveRead(u32 vaddr, unsigned bytes) = 0;
    /// Returns true when the store happened.
    virtual bool ExclusiveWrite(u32 vaddr, u64 value, unsigned bytes) = 0;

    /// CP15 register a one-word MRC (`get`) or MCR addresses, if any.
    virtual u32* Cp15Register(bool get, bool two, unsigned opc1, unsigned crn, unsigned crm,
                              unsigned opc2) = 0;
};

/// Runs translated code on one core.
class Runner {
public:
    Runner(Memory::MemorySystem& memory, Host& host);
    ~Runner();

    /// Runs from the backend's current location until code without a
    /// translation, the end of the time slice, or a halt request. Returns false,
    /// touching nothing, when the current location is not translated.
    bool Run(u64 descriptor, Memory::PageTable& page_table);

    // Env callbacks (public for the C thunks in runtime.cpp).
    DekuiAot::Abi::State state;
    Memory::MemorySystem& memory;
    Host& host;

    void BeforeCallback();
    void AfterCallback();

private:
    DekuiAot::Abi::Env env;
    u64 cycles_to_run = 0;
};

} // namespace Core::Aot
